+import { Worker } from 'worker_threads';
+
+export class WorkerPool {
+  private workers: Worker[] = [];
+  private queue: Array<{ task: unknown; resolve: Function; reject: Function }> = [];
+
+  constructor(private size: number) {
+    for (let i = 0; i < size; i++) {
+      const worker = new Worker('./scorer.js');
+      worker.on('message', (result) => {
+        /* resolve task */
+      });
+      this.workers.push(worker);
+    }
+  }
+
+  run(task: unknown): Promise<unknown> {
+    return new Promise((resolve, reject) => {
+      this.queue.push({ task, resolve, reject });
+      this.dispatch();
+    });
+  }
+
+  private dispatch() {
+    const worker = this.workers.find((w) => !w.onmessage); // pseudo check
+    if (worker && this.queue.length > 0) {
+      const item = this.queue.shift()!;
+      worker.postMessage(item.task);
+    }
+  }
+}
